<script lang="ts">
  import { onMount } from 'svelte';
  import { goto } from '$app/navigation';
  import { Activity, RefreshCw, ShieldCheck } from '@lucide/svelte';
  import Button from '$lib/components/ui/Button.svelte';
  import Card from '$lib/components/ui/Card.svelte';
  import type { MonitoringSnapshot } from '$lib/types';
  import { api } from '$lib/api';
  import { formatDate } from '$lib/utils';
  let data: MonitoringSnapshot | null = null; let loading = true; let error = '';
  async function load() { loading = true; error = ''; try { data = await api.getMonitoring(); } catch (err) { error = err instanceof Error ? err.message : 'Monitoring tidak dapat dimuat'; } finally { loading = false; } }
  onMount(async () => { try { const auth = await api.getAuthMe(); if (!auth.isAdmin) { await goto('/'); return; } } catch { await goto('/'); return; } await load(); });
</script>

<svelte:head><title>Monitoring | StockScope</title></svelte:head>
<div class="mx-auto max-w-6xl space-y-7"><section class="flex items-end justify-between gap-4"><div><p class="eyebrow">Operations</p><h1 class="mt-2 text-3xl font-bold tracking-tight">Worker monitoring</h1><p class="mt-2 text-sm text-[#6d6a63]">Kesehatan queue, scraper, resource VPS, dan koneksi CDP.</p></div><Button variant="outline" size="sm" on:click={load} disabled={loading}><RefreshCw size={14} class={loading ? 'animate-spin' : ''} /> Refresh</Button></section>{#if error}<div class="rounded-md border border-[#b94035]/25 bg-[#fff0ee] p-3 text-sm text-[#a3372f]">{error}</div>{/if}{#if loading}<Card className="p-12 text-center text-sm text-[#77736b]">Loading metrics...</Card>{:else if data}<div class="grid gap-3 sm:grid-cols-4"><Card className="p-5"><p class="text-xs font-semibold uppercase tracking-wider text-[#8d897f]">Active jobs</p><p class="mt-2 text-3xl font-bold text-[#956a1b]">{data.worker.activeJobs}</p><p class="mt-1 text-[11px] text-[#9a958b]">Concurrency {data.worker.concurrency}</p></Card><Card className="p-5"><p class="text-xs font-semibold uppercase tracking-wider text-[#8d897f]">Avg duration</p><p class="mt-2 text-3xl font-bold">{data.runs.averageDurationSeconds ?? '--'}s</p><p class="mt-1 text-[11px] text-[#9a958b]">Completed runs sampled</p></Card><Card className="p-5"><p class="text-xs font-semibold uppercase tracking-wider text-[#8d897f]">Retries</p><p class="mt-2 text-3xl font-bold text-[#a74630]">{data.scraper.retries}</p><p class="mt-1 text-[11px] text-[#9a958b]">Query retry events</p></Card><Card className="p-5"><p class="text-xs font-semibold uppercase tracking-wider text-[#8d897f]">Partial runs</p><p class="mt-2 text-3xl font-bold text-[#a3372f]">{data.scraper.partialRuns}</p><p class="mt-1 text-[11px] text-[#9a958b]">Needs review</p></Card></div><div class="grid gap-6 lg:grid-cols-2"><Card className="p-5"><div class="flex items-center gap-2"><Activity size={16} class="text-[#d75a3b]" /><h2 class="text-sm font-bold">VPS resources</h2></div><div class="mt-5 grid grid-cols-2 gap-4 text-xs"><div><p class="text-[#8d897f]">CPU estimate</p><p class="mt-1 font-mono font-bold">{data.system.cpu.estimatedPercent}%</p></div><div><p class="text-[#8d897f]">Backend CPU</p><p class="mt-1 font-mono font-bold">{data.system.cpu.processPercent}%</p></div><div><p class="text-[#8d897f]">RAM used</p><p class="mt-1 font-mono font-bold">{data.system.memory.usedPercent}%</p></div><div><p class="text-[#8d897f]">Backend RSS</p><p class="mt-1 font-mono font-bold">{data.system.memory.processRssMb} MB</p></div></div><p class="mt-5 text-[11px] text-[#9a958b]">Load 1m {data.system.cpu.load1m} · Free RAM {data.system.memory.freeMb} MB</p></Card><Card className="p-5"><div class="flex items-center gap-2"><ShieldCheck size={16} class="text-[#39704a]" /><h2 class="text-sm font-bold">Browser CDP</h2></div><div class="mt-5 flex items-center gap-3"><span class={`h-2.5 w-2.5 rounded-full ${!data.system.cdp.configured ? 'bg-[#b2ada3]' : data.system.cdp.reachable ? 'bg-[#5a9b6c]' : 'bg-[#b94035]'}`}></span><span class="text-sm font-semibold">{!data.system.cdp.configured ? 'Not configured' : data.system.cdp.reachable ? 'Reachable' : 'Unavailable'}</span></div><p class="mt-3 text-[11px] text-[#9a958b]">{data.system.cdp.browserVersion ?? 'No browser version reported'}</p></Card></div><div class="grid gap-6 lg:grid-cols-2"><Card className="p-5"><h2 class="text-sm font-bold">Worker health</h2><dl class="mt-5 space-y-3 text-xs"><div class="flex justify-between"><dt class="text-[#8d897f]">Max attempts</dt><dd class="font-mono font-bold">{data.worker.maxAttempts}</dd></div><div class="flex justify-between"><dt class="text-[#8d897f]">Stale threshold</dt><dd class="font-mono font-bold">{data.worker.staleThresholdMinutes} min</dd></div><div class="flex justify-between"><dt class="text-[#8d897f]">Last heartbeat</dt><dd class="font-mono font-bold">{data.worker.lastHeartbeatAt ? formatDate(data.worker.lastHeartbeatAt) : 'No active job'}</dd></div><div class="flex justify-between"><dt class="text-[#8d897f]">Recovered jobs</dt><dd class="font-mono font-bold">{data.scraper.recoveredJobs}</dd></div></dl></Card><Card className="p-5"><h2 class="text-sm font-bold">Run status</h2><div class="mt-5 grid grid-cols-2 gap-3">{#each Object.entries(data.runs.byStatus) as [status, count]}<div class="rounded-md border border-[#e4e0d7] bg-[#f7f5f0] p-3"><p class="text-xs capitalize text-[#8d897f]">{status}</p><p class="mt-1 font-mono text-lg font-bold">{count}</p></div>{/each}</div></Card></div>{/if}</div>
